#!/usr/bin/env -S uv run --script
# /// script
# requires-python = ">=3.13"
# [tool.ty.environment]
# root = ["."]
# ///

import sys

from hook_io import event_name_of, read_payload, run_hook, write_context

NOTES = {
    "agent-roles": (
        "Start workers as misticos agents, picked by the role in their "
        "descriptions, including workflow agents through agentType. Use a "
        "built-in agent type only when no role fits."
    ),
    "pr-body": (
        "The tool may have appended harness text to the pull request body, "
        'such as a "Generated by" footer or a session link. Read the body back '
        "now and remove that text. If you cannot edit the pull request, ask "
        "your parent agent to remove it."
    ),
}


def main() -> None:
    name = sys.argv[1]
    payload = read_payload()
    event = event_name_of(payload)
    if event:
        write_context(event, NOTES[name])


if __name__ == "__main__":
    run_hook(main)
